#pragma once
#include "routefiles.h"
#include "trafficpermanent.h"
namespace permanentroutes {
struct Entry {routefiles::File file;trafficdata::Data context;};
inline Entry Parse(const std::string& text,const std::string& name,const std::string& world){Entry out;out.file.worldId=world;out.file.traffic=false;if(text.empty())return out;if(!trafficpermanent::Owned(text))throw std::runtime_error("Shared file is not an owned permanent entry");std::vector<std::string> problems;if(!routefiles::Parse(text,name,out.file,problems)||!problems.empty()||(!world.empty()&&trafficdata::Lower(out.file.worldId)!=trafficdata::Lower(world)))throw std::runtime_error("Permanent entry is malformed or belongs to another world; preserved");trafficdata::Read(text,name,out.context);return out;}
inline void Put(Entry& entry,routefiles::Route route,const trafficdata::Data& context,const std::vector<routefiles::Link>& links){route.test=false;route.removed=false;route.lanePlan.inherited=false;auto found=std::find_if(entry.file.routes.begin(),entry.file.routes.end(),[&](const auto& old){return old.id==route.id;});if(found==entry.file.routes.end())entry.file.routes.push_back(route);else *found=route;for(const auto& link:links)if(link.from==route.id||link.to==route.id){auto at=std::find_if(entry.file.links.begin(),entry.file.links.end(),[&](const auto& old){return old.id==link.id;});if(at==entry.file.links.end())entry.file.links.push_back(link);else *at=link;}
    if(const auto at=context.worlds.find(route.world);at!=context.worlds.end())entry.context.worlds[at->first]=at->second;if(const auto at=context.anchors.find(route.world);at!=context.anchors.end())entry.context.anchors[at->first]=at->second;for(const auto& group:context.groups)if(group.name==route.group||std::any_of(route.lanePlan.vehicles.lanes.begin(),route.lanePlan.vehicles.lanes.end(),[&](const auto& rule){return rule.group==group.name;})){auto at=std::find_if(entry.context.groups.begin(),entry.context.groups.end(),[&](const auto& old){return old.name==group.name;});if(at==entry.context.groups.end())entry.context.groups.push_back(group);else *at=group;}}
inline bool Erase(Entry& entry,const std::string& id){const auto count=std::erase_if(entry.file.routes,[&](const auto& route){return route.id==id;});if(!count)return false;std::erase_if(entry.file.links,[&](const auto& link){return link.from==id||link.to==id;});return true;}
inline std::string Format(const Entry& entry){std::string out=trafficpermanent::signature+routefiles::Format(entry.file);std::set<std::string> worlds,groups;for(const auto& route:entry.file.routes){worlds.insert(route.world);groups.insert(route.group);for(const auto& rule:route.lanePlan.vehicles.lanes)groups.insert(rule.group);}for(const auto& world:worlds){if(world.empty()||world==routefiles::WorldKey(entry.file.worldId)||world.front()=='#')continue;const auto id=entry.context.worlds.find(world);const auto anchors=entry.context.anchors.find(world);if(id==entry.context.worlds.end()&&anchors==entry.context.anchors.end())throw std::runtime_error("Permanent route world has no portable identity or anchors");out+="\n[world."+world+"]\n";if(id!=entry.context.worlds.end())out+="id = "+id->second+"\n";if(anchors!=entry.context.anchors.end()){out+="anchor = ";for(std::size_t i=0;i<anchors->second.size();++i){const auto& a=anchors->second[i];char form[32];std::snprintf(form,sizeof form,"%08X",a.id);out+=(i?", ":"")+std::string(form)+" "+routefiles::Num(a.at.x)+" "+routefiles::Num(a.at.y)+" "+routefiles::Num(a.at.z);}out+="\n";}}
    std::vector<trafficdata::RouteGroup> selected;for(const auto& group:entry.context.groups)if(groups.count(group.name))selected.push_back(group);return out+"\n"+routefiles::FormatGroups(selected);}
}
